def experiment(inputs):
    import random
    def run_agent(weighted):
        traces = [0, 1, 2, 3]
        history = []
        for _ in range(10000):
            if weighted and history:
                weights = [history.count(t) + 1 for t in traces]
                choice = random.choices(traces, weights=weights)[0]
            else:
                choice = random.choice(traces)
            history.append(choice)
        return history
    weighted_history = run_agent(True)
    random_history = run_agent(False)
    variance_weighted = len(set(weighted_history)) / len(weighted_history)
    variance_random = len(set(random_history)) / len(random_history)
    return {'measurements': {'behavioral_variance_reduction': [variance_weighted - variance_random]}}

